// ── WF3: Inicializar contexto del reporte ────────────────────────────────
const now = new Date();
const dateStr = now.toISOString().split('T')[0];
return [{ json: { reportDate: dateStr, generatedAt: now.toISOString(), weekNumber: Math.ceil(now.getDate() / 7) } }];

// ── WF3: Generar Reporte HTML Combinado ──────────────────────────────────
const allItems = $input.all();
const attendanceRows = allItems.filter(i => i.json.data_type === 'attendance').map(i => i.json);
const submissionRows  = allItems.filter(i => i.json.data_type === 'submission').map(i => i.json);
const now = new Date().toLocaleString('es-GT', { timeZone: 'America/Guatemala' });
const dateStr = new Date().toISOString().split('T')[0];
const reportName = 'full_report_' + dateStr + '.html';
const reportFilePath = '/data/shared/output/' + reportName;

const attTable = attendanceRows.length === 0
  ? '<tr><td colspan="6" style="text-align:center;color:#94a3b8">Sin datos de asistencia</td></tr>'
  : attendanceRows.map(r => {
    const rate = Number(r.rate || 0);
    const rateColor = rate >= 80 ? '#16a34a' : rate >= 60 ? '#d97706' : '#dc2626';
    return '<tr><td><strong>' + r.course_id + '</strong></td><td>' + r.total + '</td>' +
      '<td style="color:#16a34a">' + r.present_count + '</td>' +
      '<td style="color:#dc2626">' + r.absent_count + '</td>' +
      '<td style="color:#d97706">' + r.late_count + '</td>' +
      '<td><span style="background:' + rateColor + ';color:#fff;padding:2px 8px;border-radius:10px;font-size:12px">' + rate + '%</span></td></tr>';
  }).join('');

const subTable = submissionRows.length === 0
  ? '<tr><td colspan="5" style="text-align:center;color:#94a3b8">Sin datos de entregas</td></tr>'
  : submissionRows.map(r => {
    const lateRate = r.total_submissions > 0 ? Math.round((r.late_count / r.total_submissions) * 100) : 0;
    const lateColor = lateRate <= 10 ? '#16a34a' : lateRate <= 30 ? '#d97706' : '#dc2626';
    return '<tr><td><strong>' + r.task_id + '</strong></td><td>' + (r.task_name||'—') + '</td>' +
      '<td>' + r.total_submissions + '</td>' +
      '<td style="color:#dc2626">' + r.late_count + '</td>' +
      '<td><span style="background:' + lateColor + ';color:#fff;padding:2px 8px;border-radius:10px;font-size:12px">' + lateRate + '% tarde</span></td></tr>';
  }).join('');

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<title>Reporte Académico Semanal ${dateStr}</title>
<style>*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Segoe UI',Arial,sans-serif;background:#f1f5f9;color:#1e293b;padding:24px}
.hdr{background:linear-gradient(135deg,#7c3aed,#4f46e5);color:#fff;padding:24px;border-radius:12px;margin-bottom:20px}
.hdr h1{font-size:20px}.hdr p{opacity:.85;font-size:13px;margin-top:6px}
.section{background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,.08);margin-bottom:20px}
.sec-hdr{background:#f8fafc;padding:14px 18px;border-bottom:1px solid #e2e8f0;font-weight:700;color:#334155;font-size:15px}
table{width:100%;border-collapse:collapse}
th{background:#1e40af;color:#fff;padding:10px;text-align:left;font-size:13px}
td{padding:10px;border-bottom:1px solid #f1f5f9;font-size:13px}tr:last-child td{border:none}
.footer{text-align:center;color:#94a3b8;font-size:12px;margin-top:16px}</style></head>
<body>
<div class="hdr">
  <h1>📊 Reporte Académico Semanal</h1>
  <p>Generado: ${now} &nbsp;|&nbsp; Periodo: ${dateStr}</p>
</div>
<div class="section">
  <div class="sec-hdr">📋 Resumen de Asistencia por Curso</div>
  <table>
    <thead><tr><th>Curso</th><th>Total</th><th>Presentes</th><th>Ausentes</th><th>Tardanzas</th><th>Tasa</th></tr></thead>
    <tbody>${attTable}</tbody>
  </table>
</div>
<div class="section">
  <div class="sec-hdr">📁 Resumen de Entregas por Tarea</div>
  <table>
    <thead><tr><th>ID Tarea</th><th>Nombre</th><th>Entregas</th><th>Tardías</th><th>% Tardía</th></tr></thead>
    <tbody>${subTable}</tbody>
  </table>
</div>
<div class="footer">Sistema Automatización Académica — n8n | ${dateStr}</div>
</body></html>`;

const safe = s => String(s||'').replace(/'/g,"''");
const rpt_sql = "INSERT INTO reports (report_type, file_path, status, records_count) VALUES ('weekly_full', '" +
  safe(reportFilePath) + "', 'generated', " + (attendanceRows.length + submissionRows.length) + ")";

const emailSubject = '📊 Reporte Académico Semanal — ' + dateStr;
const emailBody = '<div style="font-family:Arial,sans-serif;max-width:560px">' +
  '<div style="background:linear-gradient(135deg,#7c3aed,#4f46e5);color:#fff;padding:20px;border-radius:10px 10px 0 0"><h2 style="margin:0">📊 Reporte Semanal Disponible</h2></div>' +
  '<div style="background:#fff;padding:20px;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 10px 10px">' +
  '<p>El reporte académico semanal ha sido generado exitosamente.</p>' +
  '<ul style="margin:12px 0;padding-left:20px"><li>Cursos analizados: ' + attendanceRows.length + '</li>' +
  '<li>Tareas analizadas: ' + submissionRows.length + '</li></ul>' +
  '<p style="color:#6b7280;font-size:13px">El archivo se encuentra en: <code>' + reportFilePath + '</code></p>' +
  '</div></div>';

return [{ json: { reportName, reportFilePath, emailSubject, emailBody, rpt_sql, generatedAt: now, totalCourses: attendanceRows.length, totalTasks: submissionRows.length },
  binary: { report: { data: Buffer.from(html).toString('base64'), mimeType:'text/html', fileName: reportName, fileExtension:'html' } } }];
